public static void main(String args[]) {
    Scanner ans = new Scanner(System.in);
    int n = ans.nextInt();
    int k = ans.nextInt();
    int[] arr = new int[n];
    for (int i = 0; i < n; i++) {
        arr[i] = ans.nextInt();
    }
    int kco = k;
    int ans1 = 0;
    for (int i = 0; i < n; i++) {
        kco = kco - arr[i];
        if (kco < 0) {
            ans1 = ans1 + 1;
            kco = k - arr[i];
        }
        if (kco == 0) {
            ans1 = ans1 + 1;
            kco = k;
        }
    }
    System.out.println(ans1);
}
